import requests

url = 'https://api.system.local/v1/system/diagnostics'
headers = {
    'Authorization': 'Bearer <token>',
    'trace_id': 'a1b2c3d4-e5f6-7890-1234-56789abcdef0',
    'Content-Type': 'application/json'
}
payload = {
    'sequence_identifier': 'C01_Initiate_Procedural_Load_Sequence',
    'target_modules': ['core_kernel'],
    'load_parameters': {
        'cpu_stress_percentage': 90
    }
}

response = requests.post(url, headers=headers, json=payload, params={'priority_level': 'critical'})
print(response.json())
